from ..section_generic import TextBasedSectionGeneric
from ..utils.logger import logger


class SectionExecutor(TextBasedSectionGeneric):
    """
    Section "executor" is a part of cus.ini config file.
    Generated content base on ue.yaml and enb.yaml.
    Example generated for CLOUD_R4A_CUS:

    [executor]
    log_level            = DEBUG
    log_global_file_name = log_global.txt
    log_dir              = /home/cus/logs
    ue_config_url        = file:///opt/cus/etc/ue.db
    ue_capabilities_url  = file:///opt/cus/etc/uecap.ini
    duplex_mode          = FDD
    hardware_platform    = FSMR4
    enb_type             = FLEXI
    start_on_cells_oos   = true
    syslog_disable       = on
    """
    def __init__(self, subsection_separator='\n'):
        super().__init__(subsection_separator)
        self._section_header = '[executor]'

    def _prepare_section_content(self, execution_config, *args, **kwargs):
        logger.debug("Generating Executor Section")
        self._section_content = [[
            self._section_header,
            'log_level            = DEBUG',
            'log_global_file_name = log_global.txt',
            'log_dir              = /home/cus/logs',
            'ue_config_url        = file:///opt/cus/etc/ue.db',
            # 'ue_capabilities_url  = file:///opt/cus/etc/uecap.ini',
            'duplex_mode          = {}'.format(execution_config['duplex_mode']),
            'hardware_platform    = {}'.format(execution_config['hardware_platform']),
            # 'enb_type             = FLEXI',
            'start_on_cells_oos   = true',
            # 'syslog_disable       = on'

        ]]
        # if execution_config['hardware_platform'] == "CUS3":
        #     self._section_content[0].append("sim_mode             = HARQ")
